package com.proofclean.config;
import com.proofclean.analysis.entity.*;import com.proofclean.analysis.repository.AnalysisProjectRepository;import com.proofclean.user.entity.*;import com.proofclean.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor
public class DataInitializer implements CommandLineRunner { private final UserRepository userRepository; private final AnalysisProjectRepository projectRepository; private final PasswordEncoder passwordEncoder; public void run(String... args){ User demo=userRepository.findByEmail("demo@proofclean.com").orElseGet(()->userRepository.save(User.builder().email("demo@proofclean.com").password(passwordEncoder.encode("password1234")).name("Demo User").role(Role.USER).build())); if(projectRepository.findByUserOrderByCreatedAtDesc(demo).isEmpty()){ projectRepository.save(seed(demo,"중고거래 게시글 사진 점검",AnalysisPurpose.SECOND_HAND,87,"송장, 전화번호, 주소 후보 탐지")); projectRepository.save(seed(demo,"SNS 업로드 사진 점검",AnalysisPurpose.SNS,74,"위치 단서, 얼굴, EXIF 후보 탐지")); projectRepository.save(seed(demo,"과제 제출 캡처 점검",AnalysisPurpose.ASSIGNMENT,68,"학번, 이메일, 화면 텍스트 후보 탐지")); } } private AnalysisProject seed(User user,String title,AnalysisPurpose purpose,int score,String summary){ return AnalysisProject.builder().user(user).title(title).purpose(purpose).status(AnalysisStatus.ANALYZED).riskScore(score).summary(summary).build(); } }
